ALTER TABLE "Service" ADD COLUMN "icon" TEXT, ADD COLUMN "featured" BOOLEAN NOT NULL DEFAULT false, ADD COLUMN "sortOrder" INTEGER NOT NULL DEFAULT 0;
ALTER TABLE "Appointment" ALTER COLUMN "serviceId" DROP NOT NULL, ADD COLUMN "specialtyId" TEXT, ADD COLUMN "doctorId" TEXT;
CREATE TABLE "Specialty" ("id" TEXT NOT NULL, "slug" TEXT NOT NULL, "nameEn" TEXT NOT NULL, "nameAr" TEXT NOT NULL, "descriptionEn" TEXT NOT NULL, "descriptionAr" TEXT NOT NULL, "icon" TEXT, "imageUrl" TEXT, "featured" BOOLEAN NOT NULL DEFAULT false, "published" BOOLEAN NOT NULL DEFAULT true, "sortOrder" INTEGER NOT NULL DEFAULT 0, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Specialty_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "Specialty_slug_key" ON "Specialty"("slug");
CREATE TABLE "Doctor" ("id" TEXT NOT NULL, "slug" TEXT NOT NULL, "nameEn" TEXT NOT NULL, "nameAr" TEXT NOT NULL, "titleEn" TEXT NOT NULL, "titleAr" TEXT NOT NULL, "shortDescriptionEn" TEXT NOT NULL, "shortDescriptionAr" TEXT NOT NULL, "biographyEn" TEXT NOT NULL, "biographyAr" TEXT NOT NULL, "imageUrl" TEXT, "specialtyId" TEXT NOT NULL, "qualificationsEn" TEXT NOT NULL, "qualificationsAr" TEXT NOT NULL, "experienceEn" TEXT NOT NULL, "experienceAr" TEXT NOT NULL, "languagesEn" TEXT NOT NULL, "languagesAr" TEXT NOT NULL, "clinicEn" TEXT NOT NULL, "clinicAr" TEXT NOT NULL, "consultationPrice" DECIMAL(10,2), "scheduleEn" TEXT, "scheduleAr" TEXT, "featured" BOOLEAN NOT NULL DEFAULT false, "published" BOOLEAN NOT NULL DEFAULT true, "sortOrder" INTEGER NOT NULL DEFAULT 0, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Doctor_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "Doctor_slug_key" ON "Doctor"("slug"); CREATE INDEX "Doctor_specialtyId_published_sortOrder_idx" ON "Doctor"("specialtyId", "published", "sortOrder");
CREATE TABLE "_DoctorToService" ("A" TEXT NOT NULL, "B" TEXT NOT NULL); CREATE UNIQUE INDEX "_DoctorToService_AB_unique" ON "_DoctorToService"("A", "B"); CREATE INDEX "_DoctorToService_B_index" ON "_DoctorToService"("B");
CREATE TABLE "InsuranceProvider" ("id" TEXT NOT NULL, "nameEn" TEXT NOT NULL, "nameAr" TEXT NOT NULL, "logoUrl" TEXT, "website" TEXT, "descriptionEn" TEXT, "descriptionAr" TEXT, "featured" BOOLEAN NOT NULL DEFAULT false, "published" BOOLEAN NOT NULL DEFAULT true, "sortOrder" INTEGER NOT NULL DEFAULT 0, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "InsuranceProvider_pkey" PRIMARY KEY ("id"));
CREATE TABLE "SiteSettings" ("id" TEXT NOT NULL DEFAULT 'default', "siteName" TEXT NOT NULL DEFAULT 'Beit El Teb', "logoUrl" TEXT, "faviconUrl" TEXT, "phone" TEXT, "whatsapp" TEXT, "email" TEXT, "addressEn" TEXT, "addressAr" TEXT, "googleMapsUrl" TEXT, "workingHoursEn" TEXT, "workingHoursAr" TEXT, "facebook" TEXT, "instagram" TEXT, "linkedin" TEXT, "youtube" TEXT, "seoTitle" TEXT, "seoDescription" TEXT, "ogImageUrl" TEXT, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "SiteSettings_pkey" PRIMARY KEY ("id"));
CREATE TABLE "HomepageContent" ("id" TEXT NOT NULL DEFAULT 'default', "heroTitleEn" TEXT NOT NULL, "heroTitleAr" TEXT NOT NULL, "heroDescriptionEn" TEXT NOT NULL, "heroDescriptionAr" TEXT NOT NULL, "heroImageUrl" TEXT, "primaryCtaEn" TEXT NOT NULL, "primaryCtaAr" TEXT NOT NULL, "secondaryCtaEn" TEXT NOT NULL, "secondaryCtaAr" TEXT NOT NULL, "servicesVisible" BOOLEAN NOT NULL DEFAULT true, "doctorsVisible" BOOLEAN NOT NULL DEFAULT true, "whyVisible" BOOLEAN NOT NULL DEFAULT true, "insuranceVisible" BOOLEAN NOT NULL DEFAULT true, "appointmentVisible" BOOLEAN NOT NULL DEFAULT true, "whyTitleEn" TEXT NOT NULL, "whyTitleAr" TEXT NOT NULL, "whyDescriptionEn" TEXT NOT NULL, "whyDescriptionAr" TEXT NOT NULL, "ctaTitleEn" TEXT NOT NULL, "ctaTitleAr" TEXT NOT NULL, "ctaDescriptionEn" TEXT NOT NULL, "ctaDescriptionAr" TEXT NOT NULL, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "HomepageContent_pkey" PRIMARY KEY ("id"));
ALTER TABLE "Doctor" ADD CONSTRAINT "Doctor_specialtyId_fkey" FOREIGN KEY ("specialtyId") REFERENCES "Specialty"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "Appointment" ADD CONSTRAINT "Appointment_specialtyId_fkey" FOREIGN KEY ("specialtyId") REFERENCES "Specialty"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "Appointment" ADD CONSTRAINT "Appointment_doctorId_fkey" FOREIGN KEY ("doctorId") REFERENCES "Doctor"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "_DoctorToService" ADD CONSTRAINT "_DoctorToService_A_fkey" FOREIGN KEY ("A") REFERENCES "Doctor"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "_DoctorToService" ADD CONSTRAINT "_DoctorToService_B_fkey" FOREIGN KEY ("B") REFERENCES "Service"("id") ON DELETE CASCADE ON UPDATE CASCADE;
